19	function sendJson(res, status, payload, etag) {
20	  const headers = { 'content-type': 'application/json; charset=utf-8' };
21	  if (etag) headers.etag = etag;
22	  res.writeHead(status, headers);
23	  res.end(JSON.stringify(payload));
