26	async function readBody(req) {
27	  const declared = Number(req.headers['content-length']);
28	  if (Number.isFinite(declared) && declared > MAX_BODY_BYTES) {
29	    req.resume();
30	    throw new HttpError(413, 'PAYLOAD_TOO_LARGE', 'request body exceeds 1 MiB');
31	  }
32	  const chunks = [];
33	  let size = 0;
34	  for await (const chunk of req) {
35	    size += chunk.length;
36	    if (size > MAX_BODY_BYTES) {
37	      throw new HttpError(413, 'PAYLOAD_TOO_LARGE', 'request body exceeds 1 MiB');
38	    }
39	    chunks.push(chunk);
40	  }
41	  return Buffer.concat(chunks).toString('utf8');
