75	// A document server holds one Workspace and, when a history store is supplied,
76	// a per-document revision ledger. Every committed change is persisted through
77	// `save(snapshot, historySnapshot)` before the in-memory state is swapped, so a
78	// failed save leaves memory, queries, history, and the original files
79	// untouched. Everything here is synchronous, so a commit is atomic with
80	// respect to other requests.
81	export function createDocumentServer({ workspace, save, history = null }) {
82	  let current = workspace;
83	  let ledger = history;
84	
85	  const currentEtag = () => `"${current.exportJSON().checksum}"`;
