1	import crypto from 'node:crypto';
2	import { SnapshotError, snapshotFromDocuments } from './workspace.js';
3	
4	const HISTORY_VERSION = 1;
5	const HISTORY_KEYS = ['version', 'history', 'snapshot', 'checksum'];
6	const ENTRY_KEYS = ['revision', 'action', 'document'];
7	const DOCUMENT_KEYS = ['id', 'title', 'body', 'tags'];
8	const ACTIONS = new Set(['baseline', 'create', 'replace', 'delete', 'restore']);
9	const CHECKSUM_PATTERN = /^[0-9a-f]{64}$/u;
10	const ID_PATTERN = /^[a-z0-9][a-z0-9._-]*$/u;
11	
12	export class HistoryError extends Error {
13	  constructor(code, message) {
14	    super(message);
15	    this.name = 'HistoryError';
16	    this.code = code;
17	  }
18	}
19	
20	function compareCodePoints(a, b) {
21	  const left = Array.from(a, (char) => char.codePointAt(0));
22	  const right = Array.from(b, (char) => char.codePointAt(0));
23	  for (let i = 0; i < Math.min(left.length, right.length); i += 1) {
24	    if (left[i] !== right[i]) return left[i] - right[i];
25	  }
26	  return left.length - right.length;
27	}
28	
29	// A stored document uses the normalized snapshot shape: trimmed title, body
30	// verbatim, tags lowercased, deduplicated, and sorted.
31	function canonicalDocument(document) {
32	  const tags = [...new Set(
33	    document.tags.map((tag) => String(tag).trim().toLowerCase()).filter(Boolean),
34	  )].sort();
35	  return {
36	    id: document.id,
37	    title: document.title.trim(),
38	    body: document.body,
39	    tags,
40	  };
41	}
42	
43	function hashHistory(history, snapshotChecksum) {
44	  return crypto
45	    .createHash('sha256')
46	    .update(JSON.stringify({ version: HISTORY_VERSION, history, snapshot: snapshotChecksum }), 'utf8')
47	    .digest('hex');
48	}
49	
50	export function sameDocument(a, b) {
51	  return a.id === b.id && a.title === b.title && a.body === b.body
52	    && a.tags.length === b.tags.length && a.tags.every((tag, i) => tag === b.tags[i]);
53	}
54	
55	function isPlainObject(value) {
56	  return value !== null && typeof value === 'object' && !Array.isArray(value);
57	}
58	
59	function sameKeys(object, expected) {
60	  const keys = Object.keys(object);
61	  return keys.length === expected.length && expected.every((key) => keys.includes(key));
62	}
63	
64	function canonicalRecords(records) {
65	  const history = {};
66	  for (const id of [...records.keys()].sort(compareCodePoints)) {
67	    history[id] = records.get(id).map((entry) => ({
68	      revision: entry.revision,
69	      action: entry.action,
70	      document: entry.document === null ? null : canonicalDocument(entry.document),
71	    }));
72	  }
73	  return history;
74	}
75	
76	// Replays the final state of every document chain. Documents whose final entry
77	// is a delete are absent; their ids are returned in `deleted`.
78	function replay(records) {
79	  const documents = new Map();
80	  const deleted = new Set();
81	  for (const [id, entries] of records) {
82	    const last = entries[entries.length - 1];
83	    if (last.document === null) {
84	      deleted.add(id);
85	    } else {
86	      documents.set(id, canonicalDocument(last.document));
87	      deleted.delete(id);
88	    }
89	  }
90	  return { documents, deleted };
91	}
92	
93	// Validates the checksummed history payload, replays every per-document chain,
94	// and verifies the embedded snapshot checksum matches the replayed content.
95	// Returns { records, snapshotChecksum }.
96	export function parseHistory(data) {
97	  let raw = data;
98	  if (typeof raw === 'string') {
99	    try {
100	      raw = JSON.parse(raw);
101	    } catch {
102	      throw new HistoryError('INVALID_HISTORY', 'history is not valid JSON');
103	    }
104	  }
105	  if (!isPlainObject(raw)) throw new HistoryError('INVALID_HISTORY', 'history must be an object');
106	  if (!sameKeys(raw, HISTORY_KEYS)) {
