8	function demo() {
9	  const workspace = new Workspace();
10	  workspace.add({ id: 'welcome', title: '欢迎使用', body: '从 [[architecture]] 开始了解工作台。', tags: ['入门', 'Markdown'] });
11	  workspace.add({ id: 'architecture', title: '架构备忘', body: '本地优先的文档与双向链接基线。返回 [[welcome]]。', tags: ['架构', 'markdown'] });
12	  const result = {
13	    product: 'Lattice Workbench',
14	    documents: workspace.list(),
15	    search: workspace.search('markdown').map(({ id, title }) => ({ id, title })),
16	    relationships: Object.fromEntries(workspace.list().map(({ id }) => [id, workspace.links(id)])),
17	  };
18	  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
19	}
20	
21	function readSnapshotFile(file) {
22	  try {
23	    return fs.readFileSync(file, 'utf8');
24	  } catch (error) {
25	    throw new SnapshotError('IO_ERROR', `cannot read snapshot file ${file}: ${error.message}`);
26	  }
27	}
28	
29	function atomicWrite(file, content) {
30	  const directory = path.dirname(path.resolve(file));
31	  const temp = stagingPath(file);
32	  try {
33	    fs.writeFileSync(temp, content, 'utf8');
34	    fs.renameSync(temp, file);
35	  } catch (error) {
36	    try {
37	      fs.rmSync(temp, { force: true });
38	    } catch {
39	      // best-effort cleanup of the staging file
40	    }
41	    throw new SnapshotError('IO_ERROR', `cannot write snapshot file ${file}: ${error.message}`);
42	  }
43	}
44	
45	function stagingPath(file) {
46	  const directory = path.dirname(path.resolve(file));
47	  return path.join(directory, `.${path.basename(file)}.${process.pid}.tmp`);
48	}
49	
50	function parseMigrateArgs(args) {
51	  const positionals = [];
52	  let dryRun = false;
53	  for (const arg of args) {
54	    if (arg === '--dry-run') {
55	      dryRun = true;
56	    } else if (arg.startsWith('--')) {
57	      throw new SnapshotError('INVALID_OPTIONS', `unknown option: ${arg}`);
58	    } else {
59	      positionals.push(arg);
60	    }
61	  }
62	  if (positionals.length !== 4) {
63	    throw new SnapshotError('INVALID_OPTIONS', 'usage: migrate <base> <incoming> <output> <mode> [--dry-run]');
64	  }
65	  const [base, incoming, output, mode] = positionals;
66	  if (mode !== 'merge' && mode !== 'replace') {
