    assert.deepEqual(result.body.documents, [
      { id: 'a', title: 'Alpha v2', body: 'now links [[c]]', tags: [] },
      { id: 'c', title: 'Gamma', body: 'fresh [[a]]', tags: ['new'] },
    ]);

